function validate([nums1, nums2, k]) {
  if (nums1.length < 1 || nums1.length > 50) return 'nums1 needs 1 to 50 values.';
  if (nums2.length < 1 || nums2.length > 50) return 'nums2 needs 1 to 50 values.';
  if ([...nums1, ...nums2].some(v => !Number.isInteger(v) || v < 1 || v > 50)) return 'Every value is an integer from 1 to 50.';
  if (!Number.isInteger(k) || k < 1 || k > 50) return 'k is an integer from 1 to 50.';
  return null;
}

