function numberOfPairs(nums1, nums2, k) {
  // Count nums2 values, then for each nums1 value walk its divisors that are multiples of k.
  const freq = new Map();
  for (const v of nums2) freq.set(v, (freq.get(v) || 0) + 1);
  let total = 0;
  for (const value of nums1) {
    for (let d = k; d <= value; d += k) {
      if (value % d === 0) total += freq.get(d / k) || 0;
    }
  }
  return total;
}

