function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const n = size === 'large' ? pick(45, 50) : pick(1, 6);
  const m = size === 'large' ? pick(45, 50) : pick(1, 6);
  const k = rand() < 0.6 ? pick(1, 3) : pick(1, 50);
  const top = size === 'large' || rand() < 0.3 ? 50 : pick(1, 12);
  const nums1 = Array.from({ length: n }, () => pick(1, top));
  const nums2 = Array.from({ length: m }, () => pick(1, Math.min(top, rand() < 0.5 ? 6 : 50)));
  return [nums1, nums2, k];
}
